220	    /**
221	     * Builds the customer code for a new owner, formatted {@code '<LAST3>-<NNNN>'} where LAST3 is the
222	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
223	     * sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
224	     *
225	     * @param lastName the owner's last name
226	     * @return the assigned customer code
227	     */
228	    private String nextCustomerCode(String lastName) {
229	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
230	        int sequence = this.clinicService.findAllOwners().size() + 1;
231	        return String.format("%s-%04d", prefix, sequence);
232	    }
233	
234	    /**
235	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
236	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
237	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
238	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
239	     * string is what gets stored and returned.
240	     *
241	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
242	     *
243	     * @param telephone the raw telephone value supplied by the client
244	     * @return the normalized E.164 telephone number
245	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
246	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
247	     *                                 digits after the {@code '+'})
248	     */
249	    private static String normalizeTelephone(String telephone) {
250	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
251	        String digits;
252	        if (cleaned.startsWith("+")) {
253	            digits = cleaned.substring(1);
254	        } else {
255	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
256	            digits = "61" + national;
257	        }
258	        if (!digits.matches("[0-9]{8,15}")) {
259	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
260	                "telephone could not be normalized to a valid E.164 number");
261	        }
262	        return "+" + digits;
263	    }
264	
265	    /**
266	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
267	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
268	     *
269	     * @param telephone the stored telephone value, possibly {@code null}
270	     * @return the E.164 form, or the raw value when it cannot be normalized
271	     */
272	    private static String toComparableTelephone(String telephone) {
273	        try {
274	            return normalizeTelephone(telephone);
275	        } catch (ResponseStatusException ex) {
276	            return telephone;
277	        }
278	    }
279	
280	    /**
281	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
282	     * containing at least one dot, none of the three sections containing whitespace or an
283	     * additional {@code @}.
284	     */
285	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
286	
287	    /**
288	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
289	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
290	     * value is then stored and returned lower-cased.
291	     *
292	     * @param email the raw email value supplied by the client, possibly {@code null}
293	     * @return the lower-cased email, or {@code null} when none was supplied
294	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
295	     *                                 is not a syntactically valid address
296	     */
297	    private static String normalizeEmail(String email) {
298	        if (email == null) {
299	            return null;
300	        }
301	        if (!EMAIL_PATTERN.matcher(email).matches()) {
302	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
303	                "email must be a syntactically valid address");
304	        }
305	        return email.toLowerCase(Locale.ROOT);
306	    }
307	
308	    /**
309	     * Determines whether the given normalized E.164 telephone is already used by any owner other
310	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
311	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
312	     * inputs representing the same number are treated as duplicates.
313	     *
314	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
315	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
316	     * @return {@code true} if another owner already uses the telephone
317	     */
318	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
319	        for (Owner existing : this.clinicService.findAllOwners()) {
320	            if (excludeId != null && excludeId.equals(existing.getId())) {
321	                continue;
322	            }
323	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
324	                return true;
325	            }
326	        }
327	        return false;
328	    }
329	}
